import{describe,it,expect,beforeAll}from"vitest";import{readFileSync}from"node:fs";import{resolve,dirname}from"node:path";import{fileURLToPath}from"node:url";const __dirname=dirname(fileURLToPath(import.meta.url));function loadNarasimhavarmanData(){const a=readFileSync(resolve(__dirname,"../../narasimhavarman-i-explorer/narasimhavarman-data.js"),"utf-8");return new Function(a+"\nreturn { NARASIMHAVARMAN_INFO, MAMALLAPURAM_MONUMENTS, VATAPI_CAMPAIGN, FOREIGN_RELATIONS, TIMELINE_EVENTS, REFERENCES };")()}describe("Narasimhavarman I Explorer — Data Tests",()=>{let a;beforeAll(()=>{a=loadNarasimhavarmanData()}),describe("NARASIMHAVARMAN_INFO metadata",()=>{it("contains correct Narasimhavarman I metadata and Pallava dynasty",()=>{expect(a.NARASIMHAVARMAN_INFO.id).toBe("narasimhavarman-i"),expect(a.NARASIMHAVARMAN_INFO.title).toContain("Narasimhavarman I"),expect(a.NARASIMHAVARMAN_INFO.dynasty).toContain("Pallava"),expect(a.NARASIMHAVARMAN_INFO.titles).toContain("Mamalla")}),it("has quickStats array with 6 items",()=>{expect(Array.isArray(a.NARASIMHAVARMAN_INFO.quickStats)).toBe(!0),expect(a.NARASIMHAVARMAN_INFO.quickStats.length).toBe(6)})}),describe("MAMALLAPURAM_MONUMENTS & VATAPI_CAMPAIGN",()=>{it("contains Pancha Rathas, Descent of Ganges, and Vatapi conquest details",()=>{expect(Array.isArray(a.MAMALLAPURAM_MONUMENTS)).toBe(!0),expect(a.MAMALLAPURAM_MONUMENTS.length).toBeGreaterThanOrEqual(3);const e=a.MAMALLAPURAM_MONUMENTS.find(a=>a.title.includes("Pancha Rathas"));expect(e).toBeDefined(),expect(Array.isArray(a.VATAPI_CAMPAIGN)).toBe(!0),expect(a.VATAPI_CAMPAIGN.length).toBeGreaterThanOrEqual(4)})}),describe("TIMELINE_EVENTS & REFERENCES",()=>{it("contains reign timeline and reference sources",()=>{expect(Array.isArray(a.TIMELINE_EVENTS)).toBe(!0),expect(a.TIMELINE_EVENTS.length).toBeGreaterThanOrEqual(4),expect(Array.isArray(a.REFERENCES)).toBe(!0),expect(a.REFERENCES.length).toBeGreaterThanOrEqual(2)})})});